S87=[('  let tg;if(ARCH.a26)tg=aimStep(p,dt,man);/* ARCH·82: шаги 4–12 — в подсистеме наведения */\n  else{/* ARCH·82 · откат A-26: исходный текст 1.5.21; единственное отличие — «let tg=» → «tg=» */\n  tg=man?null:pickTarget();G.tg90=man?G.aimLock:tg;if(!man){if(tg)G.noTg75=0;else tg=aimFallback(dt);}/* 0.7.5 */\n  const sp=Math.hypot(p.vx,p.vy);\n  let want;if(man){const m=mouseWorld();let L=G.aimLock;\n    if(L&&(!aimLockable(L)||Math.hypot(m.x-L.x,m.y-L.y)>L.r+70))L=G.aimLock=null;\n    if(!L){let bd=1e9;for(const e of G.enemies){if(!aimLockable(e))continue;const q=Math.hypot(m.x-e.x,m.y-e.y);if(q<e.r+26&&q<bd){bd=q;L=e;}}G.aimLock=L;}\n    const T=L||m;want=Math.atan2(T.y-p.y,T.x-p.x);}else{G.aimLock=null;want=tg?Math.atan2(aimPt(tg).y-p.y,aimPt(tg).x-p.x):sp>20?Math.atan2(p.vy,p.vx):p.ang;}\n  if(ARCH.a24)want=a24Want(p,tg,want,sp,dt,man);/* ARCH·80 A-24 */\n  p.ang+=man?clamp(angDiff(want,p.ang)*Math.min(1,dt*18),-.45,.45):angDiff(want,p.ang)*Math.min(1,dt*14);}\n', '  const tg=aimStep(p,dt,man);/* ARCH·82: шаги 4–12 — в подсистеме наведения · ARCH·87: ветка отката A-26 снята (1.5.27) */\n'), ('  const shoot=ARCH.a26?autoFireWanted(man,tg):(man?(MOUSE.down||G.enemies.some(e=>targetable(e)&&!NOAUTO.has(e.type))):!!tg);/* ARCH·82 */', '  const shoot=autoFireWanted(man,tg);/* ARCH·82 · ARCH·87 */'), ("ARCH.a26=!ARCH.off['A-26'];\n", "/* ARCH·87: флаг A-26 снят вместе с веткой отката (1.5.27); window.__archOff=['A-26'] больше ничего не меняет */\n")]
